/* ═════════ Helpers ═════════ */
const $ = (s, r = document) => r.querySelector(s);
const $$ = (s, r = document) => [...r.querySelectorAll(s)];
const esc = (s) => String(s).replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));

const SQUIGGLE = '<svg class="squiggle" viewBox="0 0 300 24" preserveAspectRatio="none" aria-hidden="true"><path d="M2 14 C 30 2, 50 24, 80 12 S 130 2, 160 13 S 215 24, 245 11 S 285 4, 298 12" pathLength="1" /></svg>';

function brandSVG(name, size = 22) {
  const b = BRANDS[name];
  if (!b) return '';
  return `<svg class="brand" width="${size}" height="${size}" viewBox="0 0 24 24" role="img" aria-label="${esc(b.title)}"><path d="${b.path}" fill="${b.hex}" /></svg>`;
}

function odometer(value) {
  const cols = [...Array(20)].map((_, k) => `<span>${k % 10}</span>`).join('');
  const inner = String(value).split('').map((c) =>
    /\d/.test(c)
      ? `<span class="odo-win" aria-hidden="true"><span class="odo-col" data-d="${c}">${cols}</span></span>`
      : `<span aria-hidden="true">${c}</span>`).join('');
  return `<span class="odo" aria-label="${value}">${inner}</span>`;
}

function art(kind, cells) {
  if (kind === 'portfolio') {
    return `<div class="art art-site">
      <div class="art-page"><i class="av"></i><i class="ln" style="width:72%"></i><i class="ln" style="width:48%"></i><div class="art-tiles"><i></i><i></i><i></i></div></div>
      <div class="art-pill">● live</div>
    </div>`;
  }
  if (kind === 'tour') {
    return `<div class="art art-tour">
      <div class="art-trip"><i class="pic"></i><i class="ln" style="width:70%"></i><i class="ln" style="width:44%"></i><b>Book now</b></div>
      <span class="art-chat me">✦ trip booked!</span>
    </div>`;
  }
  if (kind === 'agency') {
    return `<div class="art art-agency">
      <div class="art-dark"><i class="ln" style="width:30%"></i><b>We craft pixels</b><i class="ln" style="width:62%"></i><div class="art-tiles"><i></i><i></i><i></i></div></div>
    </div>`;
  }
  if (kind === 'gauge') {
    return `<div class="art art-gauge">
      <div class="art-doc">${[80, 64, 92, 58, 76, 88, 50].map((w, i) => `<i style="width:${w}%" class="${i === 2 || i === 5 ? 'flag' : ''}"></i>`).join('')}</div>
      <div class="art-ring"><svg viewBox="0 0 100 100"><circle cx="50" cy="50" r="40" class="bg"/><circle cx="50" cy="50" r="40" class="fg" pathLength="100"/></svg><b>82</b><span>risk</span></div>
    </div>`;
  }
  if (kind === 'heatmap') {
    const v = Array.from({ length: 48 }, (_, i) => (Math.sin(i * 1.3) + Math.cos(i * 0.7) + 2) / 4);
    return `<div class="art art-heat">
      <div class="art-grid">${v.map((n, i) => `<i style="--v:${n};animation-delay:${(i % 8) * 0.18}s"></i>`).join('')}</div>
      <div class="art-pill">● live risk</div>
    </div>`;
  }
  return `<div class="art art-outfit">
    <span class="art-chat">sangeet night, ₹5k, something bold?</span>
    <div class="art-looks">${[0, 1, 2].map((k) => `<div class="art-look" style="--k:${k}"><i class="h"></i><i class="t"></i><i class="b"></i></div>`).join('')}</div>
    <span class="art-chat me">✦ 3 looks ready!</span>
  </div>`;
}

/* ═════════ Render lists from DATA ═════════ */
function render() {
  // squiggles under highlighted words + the hero name
  $$('.hl, .hr-name').forEach((el) => el.insertAdjacentHTML('beforeend', SQUIGGLE));

  // hero: split the name into letters so they can slide up one by one
  const nameEl = $('.hr-name-text');
  const name = nameEl.textContent.trim();
  nameEl.setAttribute('aria-label', name);
  nameEl.innerHTML = name.split('').map((c) => `<span class="ch-mask" aria-hidden="true"><span class="ch">${esc(c)}</span></span>`).join('');

  $('#hero-counts').innerHTML = DATA.heroCounts.map((c) => `<li><b>${esc(c.value)}</b><span>${esc(c.label)}</span></li>`).join('');
  $('#about-stats').innerHTML = DATA.about.stats.map((s) => `<div class="ab-stat"><b>${esc(s.value)}</b><span>${esc(s.label)}</span></div>`).join('');

  $('#work-cards').innerHTML = DATA.projects.map((p, i) => `
    <article class="wk-card">
      <div class="wk-window" style="background:${p.color}">
        <div class="wk-bar"><i></i><i></i><i></i><span>${esc(p.title.toLowerCase().replace(/[^a-z0-9]+/g, '-'))}.app</span></div>
        <div class="wk-art">${p.image ? `<img src="${esc(p.image)}" alt="${esc(p.title)}">` : art(p.visual)}</div>
      </div>
      <div class="wk-body">
        <div class="wk-top"><span class="wk-no">0${i + 1}</span><span class="wk-tag">${esc(p.tag)}</span></div>
        <h3>${esc(p.title)}</h3>
        <p>${esc(p.text)}</p>
        <div class="chips">${p.tech.map((t) => `<span>${esc(t)}</span>`).join('')}</div>
        <div class="wk-links">${p.links.map((l, i) => `<a class="btn btn-sm ${i === 0 ? 'btn-coral' : 'btn-line'}" href="${esc(l.url)}" target="_blank" rel="noreferrer">${esc(l.label)} <span>↗</span></a>`).join('')}</div>
      </div>
    </article>`).join('');

  $('#journey-list').insertAdjacentHTML('beforeend', DATA.journey.map((j, i) => `
    <li class="jr-item ${i % 2 ? 'flip' : ''}">
      <figure class="polaroid" style="--r:${i % 2 ? 4 : -4}deg">
        <span class="tape"></span>
        <div class="polaroid-logo"><img src="${esc(j.logo)}" alt="${esc(j.org)} logo" loading="lazy"></div>
        <figcaption class="hand">${esc(j.note)}</figcaption>
      </figure>
      <span class="jr-dot"></span>
      <div class="jr-card">
        <span class="jr-year hand">${esc(j.year)}</span>
        <h3>${esc(j.title)}</h3>
        <span class="jr-org">${esc(j.org)}</span>
        <p>${esc(j.text)}</p>
      </div>
    </li>`).join(''));

  const tones = ['coral', 'white', 'peach', 'ink', 'white', 'peach'];
  $('#skill-board').innerHTML = DATA.skills.map((s, i) => `<span class="skill tone-${tones[i % tones.length]}">${esc(s)}</span>`).join('');

  $('#ach-grid').innerHTML = DATA.achievements.map((a) => `
    <article class="ach-card">
      <span class="ach-icon" aria-hidden="true">${esc(a.icon)}</span>
      <h3>${esc(a.title)}</h3>
      <span class="ach-org">${esc(a.org)}</span>
      <p>${esc(a.text)}</p>
    </article>`).join('');

  $('#cert-wall').innerHTML = DATA.certifications.map(([t, by, brand], i) => `
    <figure class="cert-frame" style="--r:${[-2, 1.5, -1, 2][i % 4]}deg">
      <span class="cert-border">
        <span class="cert-logo">${BRANDS[brand] ? brandSVG(brand, 30) : `<span style="font-size:26px;line-height:1">${esc(brand)}</span>`}</span>
        <b>${esc(t)}</b>
        <span class="cert-by">${esc(by)}</span>
        <span class="cert-seal">✓</span>
      </span>
    </figure>`).join('');

  $('#nums').innerHTML = DATA.scoreboard.map((s) => `
    <div class="num-cell">
      <div class="num-val">${odometer(s.value)}<small>${esc(s.suffix)}</small></div>
      <i class="num-line"></i>
      <div class="num-meta">${brandSVG(s.brand, 18)}<b>${esc(s.label)}</b></div>
      <span class="num-note">${esc(s.note)}</span>
    </div>`).join('');

  $('#year').textContent = new Date().getFullYear();
}

/* ═════════ Motion setup ═════════ */

let lenis = null;
function startScroll() {
  history.scrollRestoration = 'manual';
  window.scrollTo(0, 0);
  if (typeof Lenis === 'undefined') return; // falls back to native scrolling
  lenis = new Lenis({ lerp: 0.1 });
  lenis.on('scroll', ScrollTrigger.update);
  gsap.ticker.add((t) => lenis.raf(t * 1000));
  gsap.ticker.lagSmoothing(0);
  lenis.stop();
}
function goTo(target) {
  if (lenis) lenis.scrollTo(target, { offset: -30, duration: 1.4 });
  else document.querySelector(target)?.scrollIntoView({ behavior: 'smooth' });
}

const drawSquiggle = (trigger, el) =>
  gsap.to(el, { strokeDashoffset: 0, duration: 1.2, ease: 'power2.inOut', scrollTrigger: { trigger, start: 'top 80%' } });

/* ═════════ Nav ═════════ */
function initNav() {
  const nav = $('.nav');
  const burger = $('.nav-burger');
  burger.addEventListener('click', () => {
    const open = nav.classList.toggle('is-open');
    burger.setAttribute('aria-expanded', open);
  });
  $$('.nav a[href^="#"]').forEach((a) => a.addEventListener('click', (e) => {
    e.preventDefault();
    nav.classList.remove('is-open');
    burger.setAttribute('aria-expanded', 'false');
    goTo(a.getAttribute('href'));
  }));
  $$('[data-goto]').forEach((b) => b.addEventListener('click', () => goTo(b.dataset.goto)));
}

/* ═════════ Loader ═════════ */
function initLoader(onFinish) {
  const loader = $('.loader');
  gsap.fromTo('.ld-face', { scale: 0, rotate: -20 }, { scale: 1, rotate: 0, duration: 1.2, ease: 'elastic.out(1, 0.55)' });
  gsap.fromTo('.ld-bubble', { scale: 0, opacity: 0 }, { scale: 1, opacity: 1, delay: 0.5, duration: 0.8, ease: 'back.out(2.5)' });
  gsap.fromTo('.ld-bar i', { scaleX: 0 }, { scaleX: 0.85, duration: 2, ease: 'power2.out' });

  const dir = innerWidth < 820 ? 'sm' : 'lg';
  const load = (src) => new Promise((r) => { const i = new Image(); i.onload = i.onerror = r; i.src = src; });
  const t0 = performance.now();
  Promise.all([
    document.fonts?.ready,
    load(DATA.avatar),
    load(`img/stickers/${dir}/f${String(DATA.lookFrames.from).padStart(3, '0')}.webp`),
  ]).then(() => setTimeout(() => {
    gsap.timeline()
      .to('.ld-bar i', { scaleX: 1, duration: 0.3 })
      .to('.ld-face, .ld-bubble, .ld-bar', { scale: 0.6, opacity: 0, duration: 0.4, stagger: 0.05, ease: 'back.in(2)' })
      .add(onFinish)
      .to(loader, { yPercent: -100, duration: 0.9, ease: 'expo.inOut' }, '-=0.1')
      .set(loader, { display: 'none' });
  }, Math.max(0, 1500 - (performance.now() - t0))));
}

/* ═════════ Hero ═════════ */
function playHeroIntro() {
  gsap.timeline()
    .from('.hr-hello', { y: 20, opacity: 0, duration: 0.8 })
    .from('.hr-name .ch', { yPercent: 110, rotate: 8, stagger: 0.05, duration: 1.1 }, 0.1)
    .to('.hr-name .squiggle path', { strokeDashoffset: 0, duration: 1.2, ease: 'power2.inOut' }, 0.6)
    .from('.hr-sub, .hr-counts, .hr-ctas', { y: 30, opacity: 0, stagger: 0.1, duration: 1 }, 0.4)
    .from('.hr-blob', { scale: 0.6, opacity: 0, duration: 1.4, ease: 'elastic.out(1, 0.7)' }, 0.1)
    .from('.hr-person', { yPercent: 30, opacity: 0, duration: 1.2, ease: 'back.out(1.4)' }, 0.3)
    .from('.hr-note', { opacity: 0, x: -10, duration: 0.6 }, 1.6)
    .to('.hr-note .hand-arrow path', { strokeDashoffset: 0, duration: 0.8, stagger: 0.3, ease: 'power2.inOut' }, 1.6);
}

function initHero() {
  gsap.to('.hr-visual', { yPercent: -8, ease: 'none', scrollTrigger: { trigger: '.hero', start: 'top top', end: 'bottom top', scrub: true } });
}

/** The cut-out turns to look toward the visitor's cursor. */
function initLookAt() {
  const { from, to } = DATA.lookFrames;
  const c = $('#look-canvas');
  const imgs = [];
  const st = { cur: 0, target: 0, drawn: -1 };
  const dir = innerWidth < 820 ? 'sm' : 'lg';
  for (let i = from; i <= to; i++) {
    const im = new Image();
    im.src = `img/stickers/${dir}/f${String(i).padStart(3, '0')}.webp`;
    im.onload = () => { st.drawn = -1; };
    imgs[i - from] = im;
  }
  const dpr = Math.min(devicePixelRatio || 1, 2);
  new ResizeObserver(() => { c.width = c.clientWidth * dpr; c.height = c.clientHeight * dpr; st.drawn = -1; }).observe(c);
  addEventListener('pointermove', (e) => {
    const r = c.getBoundingClientRect();
    const cx = r.left + r.width / 2;
    st.target = Math.min(1, Math.max(0, (cx - e.clientX) / (r.width * 1.1)));
  });
  document.addEventListener('pointerleave', () => { st.target = 0; });
  gsap.ticker.add(() => {
    st.cur += (st.target - st.cur) * 0.08;
    const idx = Math.round(st.cur * (to - from));
    if (idx === st.drawn) return;
    let im = imgs[idx];
    if (!im?.complete || !im.naturalWidth) im = imgs.find((x) => x?.complete && x.naturalWidth);
    if (!im) return;
    st.drawn = idx;
    const ctx = c.getContext('2d');
    const k = Math.min(c.width / im.naturalWidth, c.height / im.naturalHeight);
    const w = im.naturalWidth * k, h = im.naturalHeight * k;
    ctx.clearRect(0, 0, c.width, c.height);
    ctx.drawImage(im, (c.width - w) / 2, c.height - h, w, h);
  });
}

/* ═════════ About ═════════ */
function initAbout() {
  const stack = $('#about-skills');
  const tiles = DATA.about.skillTiles;
  let order = tiles.map((_, i) => i);

  stack.innerHTML = tiles.map(([keys, label], i) => `
    <figure class="stack-card" data-i="${i}">
      <div class="sk-face"><span class="sk-logos">${keys.map((k) => brandSVG(k, keys.length > 1 ? 70 : 110)).join('')}</span></div>
      <figcaption><span class="role-kicker hand">skill ${i + 1} of ${tiles.length}</span><span class="role-name">${esc(label)}</span></figcaption>
    </figure>`).join('') + '<span class="stack-hint hand">click to see my next skill ↻</span>';

  const cards = $$('.stack-card', stack);
  const paint = () => cards.forEach((el, i) => {
    const pos = Math.min(order.indexOf(i), 3);
    el.style.zIndex = 20 - order.indexOf(i);
    el.style.setProperty('--pos', pos);
    el.style.opacity = order.indexOf(i) > 3 ? 0 : 1;
    el.classList.toggle('is-top', order.indexOf(i) === 0);
  });
  paint();

  const next = () => {
    const top = cards[order[0]];
    gsap.timeline()
      .to(top, { x: 260, y: -40, rotate: 18, duration: 0.35, ease: 'power2.in' })
      .add(() => { order = [...order.slice(1), order[0]]; paint(); })
      .to(top, { x: 0, y: 0, rotate: 0, duration: 0.5, ease: 'back.out(1.6)' });
  };
  stack.addEventListener('click', next);
  stack.addEventListener('keydown', (e) => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); next(); } });

  gsap.from('.stack-card', { y: 80, rotate: 0, opacity: 0, stagger: 0.08, duration: 1.1, ease: 'back.out(1.4)', scrollTrigger: { trigger: '.about', start: 'top 72%' } });
  gsap.from('.ab-copy > *', { y: 40, opacity: 0, stagger: 0.1, duration: 1.1, scrollTrigger: { trigger: '.ab-copy', start: 'top 80%' } });
  drawSquiggle('.ab-title', '.ab-title .squiggle path');
  gsap.from('.ab-stat', { y: 40, opacity: 0, scale: 0.9, stagger: 0.08, duration: 0.9, ease: 'back.out(1.8)', scrollTrigger: { trigger: '.ab-stats', start: 'top 88%' } });
}

/* ═════════ Work ═════════ */
function initWork() {
  const scatter = [{ x: 90, y: 60, r: -9 }, { x: 0, y: 140, r: 7 }, { x: -90, y: 40, r: -5 }];
  drawSquiggle('.wk-title', '.wk-title .squiggle path');
  const mm = gsap.matchMedia();
  // desktop: cards start tossed on a table and settle into a tidy row as you scroll
  mm.add('(min-width: 1001px)', () => {
    $$('.wk-card').forEach((c, i) => {
      const s = scatter[i % scatter.length];
      gsap.fromTo(c, { x: s.x, y: s.y, rotate: s.r }, {
        x: 0, y: 0, rotate: 0, ease: 'none',
        scrollTrigger: { trigger: '.wk-cards', start: 'top 95%', end: 'top 35%', scrub: 0.6 },
      });
    });
  });
  mm.add('(max-width: 1000px)', () => {
    $$('.wk-card').forEach((c, i) => {
      gsap.from(c, { y: 60, rotate: i % 2 ? 4 : -4, opacity: 0, duration: 1, scrollTrigger: { trigger: c, start: 'top 88%' } });
    });
  });
}

/* ═════════ Journey (scrapbook map) ═════════ */
function initJourney() {
  const list = $('#journey-list');
  const map = $('.jr-map', list);
  const road = $('#jr-road');
  const trail = $('#jr-trail');
  const walker = $('#jr-walker');
  let st = null;

  const place = (progress) => {
    const len = trail.getTotalLength();
    trail.style.strokeDashoffset = `${len * (1 - progress)}`;
    const pt = trail.getPointAtLength(len * progress);
    walker.style.transform = `translate(${pt.x}px, ${pt.y}px)`;
  };

  const build = () => {
    const r = list.getBoundingClientRect();
    const pts = $$('.jr-dot', list).map((el) => {
      const b = el.getBoundingClientRect();
      return [b.left - r.left + b.width / 2, b.top - r.top + b.height / 2];
    });
    if (!pts.length) return;
    const mobile = innerWidth < 760;
    const amp = mobile ? 22 : Math.min(260, r.width * 0.2);
    let prev = [pts[0][0], 0];
    let d = `M ${prev[0]} ${prev[1]} `;
    pts.concat([[pts[pts.length - 1][0], r.height]]).forEach((p, i) => {
      const dir = i % 2 ? 1 : -1;
      const dy = (p[1] - prev[1]) / 2;
      d += `C ${prev[0] + amp * dir} ${prev[1] + dy}, ${p[0] + amp * dir} ${p[1] - dy}, ${p[0]} ${p[1]} `;
      prev = p;
    });
    map.setAttribute('width', r.width);
    map.setAttribute('height', r.height);
    map.setAttribute('viewBox', `0 0 ${r.width || 1} ${r.height || 1}`);
    road.setAttribute('d', d);
    trail.setAttribute('d', d);
    trail.style.strokeDasharray = `${trail.getTotalLength()}`;

    // draw the road + move the avatar with scroll
    const progress = st ? st.progress : 0;
    st?.kill();
    st = ScrollTrigger.create({
      trigger: list, start: 'top 65%', end: 'bottom 65%', scrub: 0.4,
      onUpdate: (s) => place(s.progress),
    });
    place(progress);
    ScrollTrigger.refresh();
  };

  build();
  new ResizeObserver(build).observe(list);
  addEventListener('load', build);

  drawSquiggle('.jr-title', '.jr-title .squiggle path');
  $$('.jr-item').forEach((it, i) => {
    gsap.timeline({ scrollTrigger: { trigger: it, start: 'top 78%' } })
      .from($('.polaroid', it), { y: 60, rotate: i % 2 ? 14 : -14, scale: 0.8, opacity: 0, duration: 1.1, ease: 'back.out(1.6)' })
      .from($('.jr-card', it), { x: i % 2 ? -50 : 50, opacity: 0, duration: 1 }, 0.15)
      .from($('.jr-dot', it), { scale: 0, duration: 0.6, ease: 'back.out(3)' }, 0.1);
  });
}

/* ═════════ Skills (sticker board) ═════════ */
function initSkills() {
  const board = $('#skill-board');

  const layout = (animate) => {
    const els = $$('.skill', board);
    const flow = innerWidth < 700;
    board.classList.toggle('flow', flow);
    if (flow) {
      board.style.height = '';
      if (animate) els.sort(() => Math.random() - 0.5).forEach((el) => board.appendChild(el));
      els.forEach((el, k) => gsap.to(el, { x: 0, y: 0, xPercent: 0, yPercent: 0, rotate: animate ? gsap.utils.random(-8, 8) : ((k * 29) % 13) - 6, duration: animate ? 0.8 : 0, ease: 'elastic.out(1, 0.6)' }));
      return;
    }
    const cols = innerWidth < 1100 ? 4 : 5;
    const rows = Math.ceil(els.length / cols);
    const rowH = 92;
    board.style.height = `${rows * rowH + 60}px`;
    const order = els.map((_, i) => i);
    if (animate) order.sort(() => Math.random() - 0.5);
    els.forEach((el, k) => {
      const idx = order[k];
      const c = idx % cols, r = Math.floor(idx / cols);
      const jx = animate ? gsap.utils.random(-1.5, 1.5) : (((k * 37) % 7) - 3) * 0.5;
      const jy = animate ? gsap.utils.random(-12, 12) : ((k * 53) % 21) - 10;
      gsap.to(el, {
        left: `${8 + ((c + 0.5) / cols) * 84 + jx}%`,
        top: `${30 + (r + 0.5) * rowH + jy * 0.6}px`,
        x: 0, y: 0, xPercent: -50, yPercent: -50, rotate: animate ? gsap.utils.random(-14, 14) : ((k * 29) % 19) - 9,
        duration: animate ? 1.1 : 0, ease: 'elastic.out(1, 0.6)', delay: animate ? k * 0.015 : 0,
      });
    });
  };

  layout(false);
  addEventListener('resize', () => layout(false));
  $('#shuffle-skills').addEventListener('click', () => layout(true));

  drawSquiggle('.sk-title', '.sk-title .squiggle path');
  gsap.from('.skill', { scale: 0, stagger: { each: 0.03, from: 'random' }, duration: 0.7, ease: 'back.out(2.6)', scrollTrigger: { trigger: board, start: 'top 80%' } });
  Draggable.create('.skill', {
    bounds: board,
    onPress() { gsap.to(this.target, { scale: 1.15, rotate: 0, zIndex: 5, duration: 0.2 }); },
    onRelease() { gsap.to(this.target, { scale: 1, rotate: gsap.utils.random(-12, 12), zIndex: 1, duration: 0.6, ease: 'elastic.out(1, 0.5)' }); },
  });
}

/* ═════════ Milestones ═════════ */
function initAchievements() {
  $$('#achievements .squiggle path').forEach((p) =>
    gsap.to(p, { strokeDashoffset: 0, duration: 1.2, ease: 'power2.inOut', scrollTrigger: { trigger: p, start: 'top 85%' } }));
  gsap.from('.ach-card', { y: 50, rotate: (i) => (i % 2 ? 4 : -4), opacity: 0, stagger: 0.1, duration: 0.9, ease: 'back.out(1.6)', scrollTrigger: { trigger: '.ach-grid', start: 'top 85%' } });
}

function initMilestones() {
  $$('#milestones .squiggle path').forEach((p) =>
    gsap.to(p, { strokeDashoffset: 0, duration: 1.2, ease: 'power2.inOut', scrollTrigger: { trigger: p, start: 'top 85%' } }));
  gsap.from('.cert-frame', { y: 50, rotate: (i) => (i % 2 ? 8 : -8), opacity: 0, stagger: 0.06, duration: 0.9, ease: 'back.out(1.6)', scrollTrigger: { trigger: '.ms-wall', start: 'top 85%' } });

  // stats: fade up, digits roll into place, a coral line draws underneath
  const tl = gsap.timeline({ scrollTrigger: { trigger: '.nums', start: 'top 82%' } });
  tl.from('.num-cell', { y: 40, opacity: 0, stagger: 0.12, duration: 0.8, ease: 'power3.out' });
  $$('.nums .odo-col').forEach((col, i) => {
    tl.fromTo(col, { yPercent: 0 }, { yPercent: -((10 + +col.dataset.d) / 20) * 100, duration: 2.2, ease: 'power4.out' }, 0.15 + i * 0.05);
  });
  tl.from('.num-line', { scaleX: 0, stagger: 0.12, duration: 1.2, ease: 'expo.inOut' }, 0.4)
    .from('.num-meta, .num-note', { y: 12, opacity: 0, stagger: 0.08, duration: 0.6 }, 0.9);
}

/* ═════════ Contact ═════════ */
function initContact() {
  const tl = gsap.timeline({ scrollTrigger: { trigger: '.contact', start: 'top 70%' } });
  tl.from('.ct-card', { y: 80, scale: 0.94, opacity: 0, duration: 1.1 })
    .from('.ct-sticker', { yPercent: 40, rotate: 10, opacity: 0, duration: 1.1, ease: 'back.out(1.5)' }, 0.25)
    .from('.ct-bubble', { scale: 0, duration: 0.7, ease: 'back.out(3)' }, 0.9)
    .from('.ct-copy > *', { y: 30, opacity: 0, stagger: 0.08, duration: 0.9 }, 0.3);
  gsap.to('.ct-sticker', { rotate: 2, duration: 2.4, yoyo: true, repeat: -1, ease: 'sine.inOut', transformOrigin: '50% 100%' });

  const btn = $('#copy-email');
  const email = $('#ct-email').textContent.trim();
  btn.addEventListener('click', async () => {
    try {
      await navigator.clipboard.writeText(email);
      btn.textContent = 'Copied ✓';
      setTimeout(() => { btn.textContent = 'Copy'; }, 1800);
    } catch { /* clipboard not available */ }
  });
}

/* ═════════ Boot ═════════ */
function boot() {
  gsap.registerPlugin(ScrollTrigger, Draggable);
  gsap.defaults({ ease: 'power4.out', duration: 1 });
  render();
  startScroll();
  initNav();
  initHero();
  initLookAt();
  initAbout();
  initWork();
  initJourney();
  initSkills();
  initMilestones();
  initAchievements();
  initContact();
  initLoader(() => {
    playHeroIntro();
    gsap.from('.nav', { y: -80, opacity: 0, duration: 1.1, delay: 0.3 });
    lenis?.start();
    ScrollTrigger.refresh();
  });
}

if (typeof gsap === 'undefined') {
  // libraries failed to load (offline?): show the page without animation
  document.querySelector('.loader')?.remove();
} else if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', boot);
} else {
  boot();
}
